                    <select class="form-select" @bind="_language">
                        @foreach (var lang in _languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-1">Compact Mode</h6>
                        <small class="text-muted">Reduce spacing and padding throughout the UI.</small>
                    </div>
                    <div class="form-check form-switch mb-0">
                        <input class="form-check-input" type="checkbox" @bind="_compactMode" />
                    </div>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save
            </button>

            @if (_showSuccess)
            {
                <div class="alert alert-success mt-3 d-flex align-items-center" role="alert">
                    <span class="me-2">✅</span> Appearance settings saved!
                </div>
            }
        </div>

        <div class="col-md-5">
            <div class="card">
                <div class="card-header">
                    <strong>Live Preview</strong>
                </div>
                <div class="card-body preview-area @GetPreviewClasses()" style="@GetPreviewStyles()">
                    <h6>Sample Heading</h6>
