@using sv_2a9d77a83753474abe0bae46792e81fc.Services

<div class="security-section">
    <h4 class="mb-4">Security Settings</h4>

    @if (_settings is null)
    {
        <p class="text-muted">Loading...</p>
        return;
    }

    <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

    <div class="card my-4">
        <div class="card-body d-flex justify-content-between align-items-center">
            <div>
                <h6 class="mb-1">Two-Factor Authentication</h6>
                <small class="text-muted">Add an extra layer of security to your account.</small>
            </div>
            <div class="d-flex align-items-center gap-2">
                <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
                <div class="form-check form-switch mb-0">
                    <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
                </div>
            </div>
        </div>
    </div>

    @if (_settings.LastPasswordChange.HasValue)
    {
        <p class="text-muted small">
            🕒 Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
        </p>
    }

    <h5 class="mt-4 mb-3">Active Sessions</h5>
    <ActiveSessionsTable Sessions="_settings.Sessions" OnRevoke="HandleRevokeSession" />
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private SecuritySettings? _settings;
    private bool _twoFactorEnabled;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
    }

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        _settings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _settings = await SettingsService.GetSecuritySettingsAsync();
    }
