@using sv_2a9d77a83753474abe0bae46792e81fc.Services

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    @if (_settings is null)
    {
        <p class="text-muted">Loading...</p>
        return;
    }

    <div class="row">
        <div class="col-md-7">
            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title">Theme</h6>
                    @foreach (var theme in _themes)
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{theme}")" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title">Font Size</h6>
                    @foreach (var size in _fontSizes)
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{size}")" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title">Language</h6>
                    <select class="form-select" @bind="_language">
                        @foreach (var lang in _languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-1">Compact Mode</h6>
                        <small class="text-muted">Reduce spacing and padding throughout the UI.</small>
                    </div>
                    <div class="form-check form-switch mb-0">
                        <input class="form-check-input" type="checkbox" @bind="_compactMode" />
                    </div>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save
            </button>

            @if (_showSuccess)
            {
                <div class="alert alert-success mt-3 d-flex align-items-center" role="alert">
                    <span class="me-2">✅</span> Appearance settings saved!
                </div>
            }
        </div>

        <div class="col-md-5">
            <div class="card">
                <div class="card-header">
                    <strong>Live Preview</strong>
                </div>
                <div class="card-body preview-area @GetPreviewClasses()" style="@GetPreviewStyles()">
                    <h6>Sample Heading</h6>
                    <p>This is how your content will look with the selected settings.</p>
                    <div class="d-flex gap-2">
                        <button class="btn btn-sm btn-primary">Primary</button>
                        <button class="btn btn-sm btn-outline-secondary">Secondary</button>
                    </div>
                    <hr />
                    <ul class="mb-0">
                        <li>List item one</li>
                        <li>List item two</li>
                        <li>List item three</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private AppearanceSettings? _settings;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _saving;
    private bool _showSuccess;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetAppearanceAsync();
        _theme = _settings.Theme;
        _fontSize = _settings.FontSize;
        _language = _settings.Language;
        _compactMode = _settings.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (_theme == "Dark") classes.Add("preview-dark");
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private string GetPreviewStyles()
    {
        var size = _fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        return $"font-size: {size};";
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;

        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _settings = updated;

        _saving = false;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

