.preview-area {
    transition: all 0.2s ease;
    border-radius: 0.375rem;
    min-height: 200px;
}

.preview-dark {
    background-color: #1e1e2e;
    color: #cdd6f4;
}

.preview-dark .btn-primary {
    background-color: #89b4fa;
    border-color: #89b4fa;
    color: #1e1e2e;
}

.preview-dark .btn-outline-secondary {
    color: #a6adc8;
    border-color: #a6adc8;
}

.preview-dark hr {
    border-color: #45475a;
}

.preview-compact {
    padding: 0.5rem !important;
    line-height: 1.3;
}

.preview-compact h6 {
    margin-bottom: 0.25rem;
}

.preview-compact p {
    margin-bottom: 0.25rem;
}

.preview-compact ul {
    padding-left: 1rem;
}

.preview-compact li {
    margin-bottom: 0;
